{
  "name": "opencode-landstrip",
  "version": "0.20.28",
  "description": "OS-level AI command sandboxing for OpenCode with Landstrip",
  "keywords": [
    "landlock",
    "landstrip",
    "opencode-plugin",
    "sandbox"
  ],
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/landstrip/landstrip.git"
  },
  "files": [
    "index.ts",
    "tui.ts",
    "shared.ts",
    "README.md",
    "sandbox.json"
  ],
  "type": "module",
  "main": "./index.ts",
  "exports": {
    ".": {
      "import": "./index.ts",
      "types": "./index.ts"
    },
    "./server": {
      "import": "./index.ts",
      "types": "./index.ts"
    },
    "./tui": {
      "import": "./tui.ts",
      "types": "./tui.ts"
    }
  },
  "scripts": {
    "fmt": "oxfmt index.ts tui.ts shared.ts package.json tsconfig.json sandbox.json .oxfmtrc.json README.md test/*.mjs",
    "lint": "oxlint index.ts tui.ts shared.ts",
    "check": "tsc --noEmit",
    "test": "node --test test/*.test.mjs",
    "all": "npm run fmt && npm run lint && npm run check && npm test",
    "ci:fmt": "oxfmt --check index.ts tui.ts shared.ts package.json tsconfig.json sandbox.json .oxfmtrc.json README.md test/*.mjs",
    "ci:lint": "npm run lint",
    "ci:check": "npm run check",
    "ci:test": "npm test"
  },
  "dependencies": {
    "@landstrip/landstrip-api": "^0.20.28",
    "@opentui/core": ">=0.5.12",
    "@opentui/solid": ">=0.5.12",
    "semver": "^7.8.6",
    "shell-quote": "^1.12.0",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.0.18",
    "@opencode/theme": "^2.0.18",
    "@types/node": "^26.1.1",
    "@types/semver": "^7.8.0",
    "@types/shell-quote": "^1.7.5",
    "oxfmt": "^0.74.0",
    "oxlint": "^1.68.0",
    "typescript": "^5.9.3"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.0.18"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "engines": {
    "opencode": ">=2.0.18"
  }
}
